SELECT

FROM ACCOUNT_REPORT_STRATEGY
WHERE
LOGIC_DEL = 0

    AND REMARK = #{dto.remark}


    AND USER_ID = #{dto.userId}


    AND BUDGET_ID = #{dto.budgetId}


    AND BUDGET_TYPE = #{dto.budgetType}


    AND GENERATE_TIME = #{dto.generateTime}


    AND NEXT_GENERATE_TIME = #{dto.nextGenerateTime}


    AND ENABLED = #{dto.enabled}


    AND WEEK_BEGIN = #{dto.weekBegin}


    AND RECALCULATE_FLAG = #{dto.recalculateFlag}

ORDER BY create_time DESC

SELECT

FROM ACCOUNT_REPORT,ACCOUNT_REPORT_STRATEGY
WHERE LOGIC_DEL = 0

    AND REMARK = #{dto.remark}


    AND USER_ID = #{dto.userId}


    AND BUDGET_ID = #{dto.budgetId}


    AND BUDGET_TYPE = #{dto.budgetType}


    AND GENERATE_TIME = #{dto.generateTime}


    AND NEXT_GENERATE_TIME = #{dto.nextGenerateTime}


    AND ENABLED = #{dto.enabled}


    AND WEEK_BEGIN = #{dto.weekBegin}


    AND RECALCULATE_FLAG = #{dto.recalculateFlag}

ORDER BY MODIFY_TIME DESC
